     1→use super::*;
     2→use crate::VerifySignatures;
     3→use crate::common::{
     4→    get_attestation_participation_flag_indices, increase_balance, initiate_validator_exit,
     5→    slash_validator,
     6→};
     7→use crate::per_block_processing::errors::{BlockProcessingError, IntoWithIndex};
     8→use types::consts::altair::{PARTICIPATION_FLAG_WEIGHTS, PROPOSER_WEIGHT, WEIGHT_DENOMINATOR};
