    10→
    11→pub fn process_operations<E: EthSpec, Payload: AbstractExecPayload<E>>(
    12→    state: &mut BeaconState<E>,
    13→    block_body: BeaconBlockBodyRef<E, Payload>,
    14→    verify_signatures: VerifySignatures,
    15→    ctxt: &mut ConsensusContext<E>,
    16→    spec: &ChainSpec,
    17→) -> Result<(), BlockProcessingError> {
    18→    process_proposer_slashings(
    19→        state,
    20→        block_body.proposer_slashings(),
    21→        verify_signatures,
    22→        ctxt,
    23→        spec,
    24→    )?;
    25→    process_attester_slashings(
    26→        state,
    27→        block_body.attester_slashings(),
    28→        verify_signatures,
    29→        ctxt,
    30→        spec,
    31→    )?;
    32→    process_attestations(state, block_body, verify_signatures, ctxt, spec)?;
    33→    process_deposits(state, block_body.deposits(), spec)?;
    34→    process_exits(state, block_body.voluntary_exits(), verify_signatures, spec)?;
    35→
    36→    if let Ok(bls_to_execution_changes) = block_body.bls_to_execution_changes() {
    37→        process_bls_to_execution_changes(state, bls_to_execution_changes, verify_signatures, spec)?;
    38→    }
    39→
    40→    if state.fork_name_unchecked().electra_enabled() {
    41→        state.update_pubkey_cache()?;
    42→        process_deposit_requests(state, &block_body.execution_requests()?.deposits, spec)?;
    43→        process_withdrawal_requests(state, &block_body.execution_requests()?.withdrawals, spec)?;
    44→        process_consolidation_requests(
    45→            state,
    46→            &block_body.execution_requests()?.consolidations,
    47→            spec,
    48→        )?;
    49→    }
    50→
    51→    Ok(())
    52→}
    53→
    54→pub mod base {
    55→    use super::*;
    56→
    57→    /// Validates each `Attestation` and updates the state, short-circuiting on an invalid object.
    58→    ///
    59→    /// Returns `Ok(())` if the validation and state updates completed successfully, otherwise returns
    60→    /// an `Err` describing the invalid object or cause of failure.
    61→    pub fn process_attestations<'a, E: EthSpec, I>(
    62→        state: &mut BeaconState<E>,
    63→        attestations: I,
    64→        verify_signatures: VerifySignatures,
    65→        ctxt: &mut ConsensusContext<E>,
    66→        spec: &ChainSpec,
    67→    ) -> Result<(), BlockProcessingError>
    68→    where
    69→        I: Iterator<Item = AttestationRef<'a, E>>,
    70→    {
    71→        // Ensure required caches are all built. These should be no-ops during regular operation.
    72→        state.build_committee_cache(RelativeEpoch::Current, spec)?;
    73→        state.build_committee_cache(RelativeEpoch::Previous, spec)?;
    74→        initialize_epoch_cache(state, spec)?;
    75→        initialize_progressive_balances_cache(state, spec)?;
    76→        state.build_slashings_cache()?;
    77→
    78→        let proposer_index = ctxt.get_proposer_index(state, spec)?;
    79→
    80→        // Verify and apply each attestation.
    81→        for (i, attestation) in attestations.enumerate() {
    82→            verify_attestation_for_block_inclusion(
    83→                state,
    84→                attestation,
    85→                ctxt,
    86→                verify_signatures,
    87→                spec,
    88→            )
    89→            .map_err(|e| e.into_with_index(i))?;
    90→
    91→            let AttestationRef::Base(attestation) = attestation else {
    92→                // Pending attestations have been deprecated in a altair, this branch should
    93→                // never happen
    94→                return Err(BlockProcessingError::PendingAttestationInElectra);
    95→            };
    96→
    97→            let pending_attestation = PendingAttestation {
    98→                aggregation_bits: attestation.aggregation_bits.clone(),
    99→                data: attestation.data.clone(),
   100→                inclusion_delay: state.slot().safe_sub(attestation.data.slot)?.as_u64(),
   101→                proposer_index,
   102→            };
   103→
   104→            if attestation.data.target.epoch == state.current_epoch() {
   105→                state
   106→                    .as_base_mut()?
   107→                    .current_epoch_attestations
   108→                    .push(pending_attestation)?;
   109→            } else {
   110→                state
   111→                    .as_base_mut()?
   112→                    .previous_epoch_attestations
   113→                    .push(pending_attestation)?;
   114→            }
   115→        }
   116→
   117→        Ok(())
   118→    }
   119→}
   120→
   121→pub mod altair_deneb {
   122→    use super::*;
   123→    use crate::common::update_progressive_balances_cache::update_progressive_balances_on_attestation;
   124→
   125→    pub fn process_attestations<'a, E: EthSpec, I>(
   126→        state: &mut BeaconState<E>,
   127→        attestations: I,
   128→        verify_signatures: VerifySignatures,
   129→        ctxt: &mut ConsensusContext<E>,
   130→        spec: &ChainSpec,
   131→    ) -> Result<(), BlockProcessingError>
   132→    where
   133→        I: Iterator<Item = AttestationRef<'a, E>>,
   134→    {
   135→        attestations.enumerate().try_for_each(|(i, attestation)| {
   136→            process_attestation(state, attestation, i, ctxt, verify_signatures, spec)
   137→        })
   138→    }
   139→
   140→    pub fn process_attestation<E: EthSpec>(
   141→        state: &mut BeaconState<E>,
   142→        attestation: AttestationRef<E>,
   143→        att_index: usize,
   144→        ctxt: &mut ConsensusContext<E>,
   145→        verify_signatures: VerifySignatures,
   146→        spec: &ChainSpec,
   147→    ) -> Result<(), BlockProcessingError> {
   148→        let proposer_index = ctxt.get_proposer_index(state, spec)?;
   149→        let previous_epoch = ctxt.previous_epoch;
   150→        let current_epoch = ctxt.current_epoch;
   151→
   152→        let indexed_att = verify_attestation_for_block_inclusion(
   153→            state,
   154→            attestation,
   155→            ctxt,
   156→            verify_signatures,
   157→            spec,
   158→        )
   159→        .map_err(|e| e.into_with_index(att_index))?;
   160→
   161→        // Matching roots, participation flag indices
   162→        let data = attestation.data();
   163→        let inclusion_delay = state.slot().safe_sub(data.slot)?.as_u64();
   164→        let participation_flag_indices =
   165→            get_attestation_participation_flag_indices(state, data, inclusion_delay, spec)?;
   166→
   167→        // Update epoch participation flags.
   168→        let mut proposer_reward_numerator = 0;
   169→        for index in indexed_att.attesting_indices_iter() {
   170→            let index = *index as usize;
   171→
   172→            let validator_effective_balance = state.epoch_cache().get_effective_balance(index)?;
   173→            let validator_slashed = state.slashings_cache().is_slashed(index);
   174→
   175→            for (flag_index, &weight) in PARTICIPATION_FLAG_WEIGHTS.iter().enumerate() {
   176→                let epoch_participation = state.get_epoch_participation_mut(
   177→                    data.target.epoch,
   178→                    previous_epoch,
   179→                    current_epoch,
   180→                )?;
   181→
   182→                if participation_flag_indices.contains(&flag_index) {
   183→                    let validator_participation = epoch_participation
   184→                        .get_mut(index)
   185→                        .ok_or(BeaconStateError::ParticipationOutOfBounds(index))?;
   186→
   187→                    if !validator_participation.has_flag(flag_index)? {
   188→                        validator_participation.add_flag(flag_index)?;
   189→                        proposer_reward_numerator
   190→                            .safe_add_assign(state.get_base_reward(index)?.safe_mul(weight)?)?;
   191→
   192→                        update_progressive_balances_on_attestation(
   193→                            state,
   194→                            data.target.epoch,
   195→                            flag_index,
   196→                            validator_effective_balance,
   197→                            validator_slashed,
   198→                        )?;
   199→                    }
   200→                }
   201→            }
   202→        }
   203→
   204→        let proposer_reward_denominator = WEIGHT_DENOMINATOR
   205→            .safe_sub(PROPOSER_WEIGHT)?
   206→            .safe_mul(WEIGHT_DENOMINATOR)?
   207→            .safe_div(PROPOSER_WEIGHT)?;
   208→        let proposer_reward = proposer_reward_numerator.safe_div(proposer_reward_denominator)?;
   209→        increase_balance(state, proposer_index as usize, proposer_reward)?;
   210→        Ok(())
   211→    }
   212→}
   213→
   214→/// Validates each `ProposerSlashing` and updates the state, short-circuiting on an invalid object.
   215→///
   216→/// Returns `Ok(())` if the validation and state updates completed successfully, otherwise returns
   217→/// an `Err` describing the invalid object or cause of failure.
   218→pub fn process_proposer_slashings<E: EthSpec>(
   219→    state: &mut BeaconState<E>,
   220→    proposer_slashings: &[ProposerSlashing],
   221→    verify_signatures: VerifySignatures,
   222→    ctxt: &mut ConsensusContext<E>,
   223→    spec: &ChainSpec,
   224→) -> Result<(), BlockProcessingError> {
   225→    state.build_slashings_cache()?;
   226→
   227→    // Verify and apply proposer slashings in series.
   228→    // We have to verify in series because an invalid block may contain multiple slashings
   229→    // for the same validator, and we need to correctly detect and reject that.
   230→    proposer_slashings
   231→        .iter()
   232→        .enumerate()
   233→        .try_for_each(|(i, proposer_slashing)| {
   234→            verify_proposer_slashing(proposer_slashing, state, verify_signatures, spec)
   235→                .map_err(|e| e.into_with_index(i))?;
   236→
   237→            slash_validator(
   238→                state,
   239→                proposer_slashing.signed_header_1.message.proposer_index as usize,
   240→                None,
   241→                ctxt,
   242→                spec,
   243→            )?;
   244→
   245→            Ok(())
   246→        })
   247→}
   248→
   249→/// Validates each `AttesterSlashing` and updates the state, short-circuiting on an invalid object.
   250→///
   251→/// Returns `Ok(())` if the validation and state updates completed successfully, otherwise returns
   252→/// an `Err` describing the invalid object or cause of failure.
   253→pub fn process_attester_slashings<'a, E: EthSpec, I>(
   254→    state: &mut BeaconState<E>,
   255→    attester_slashings: I,
   256→    verify_signatures: VerifySignatures,
   257→    ctxt: &mut ConsensusContext<E>,
   258→    spec: &ChainSpec,
   259→) -> Result<(), BlockProcessingError>
   260→where
   261→    I: Iterator<Item = AttesterSlashingRef<'a, E>>,
   262→{
   263→    state.build_slashings_cache()?;
   264→
   265→    for (i, attester_slashing) in attester_slashings.enumerate() {
   266→        let slashable_indices =
   267→            verify_attester_slashing(state, attester_slashing, verify_signatures, spec)
   268→                .map_err(|e| e.into_with_index(i))?;
   269→
   270→        for i in slashable_indices {
   271→            slash_validator(state, i as usize, None, ctxt, spec)?;
   272→        }
   273→    }
   274→
   275→    Ok(())
   276→}
