   278→/// Wrapper function to handle calling the correct version of `process_attestations` based on
   279→/// the fork.
   280→pub fn process_attestations<E: EthSpec, Payload: AbstractExecPayload<E>>(
   281→    state: &mut BeaconState<E>,
   282→    block_body: BeaconBlockBodyRef<E, Payload>,
   283→    verify_signatures: VerifySignatures,
   284→    ctxt: &mut ConsensusContext<E>,
   285→    spec: &ChainSpec,
   286→) -> Result<(), BlockProcessingError> {
   287→    if state.fork_name_unchecked().altair_enabled() {
   288→        altair_deneb::process_attestations(
   289→            state,
   290→            block_body.attestations(),
   291→            verify_signatures,
   292→            ctxt,
   293→            spec,
   294→        )?;
   295→    } else {
   296→        base::process_attestations(
   297→            state,
   298→            block_body.attestations(),
   299→            verify_signatures,
   300→            ctxt,
   301→            spec,
   302→        )?;
   303→    }
   304→    Ok(())
   305→}
   306→
   307→/// Validates each `Exit` and updates the state, short-circuiting on an invalid object.
   308→///
   309→/// Returns `Ok(())` if the validation and state updates completed successfully, otherwise returns
   310→/// an `Err` describing the invalid object or cause of failure.
   311→pub fn process_exits<E: EthSpec>(
   312→    state: &mut BeaconState<E>,
   313→    voluntary_exits: &[SignedVoluntaryExit],
   314→    verify_signatures: VerifySignatures,
   315→    spec: &ChainSpec,
   316→) -> Result<(), BlockProcessingError> {
   317→    // Verify and apply each exit in series. We iterate in series because higher-index exits may
   318→    // become invalid due to the application of lower-index ones.
   319→    for (i, exit) in voluntary_exits.iter().enumerate() {
   320→        verify_exit(state, None, exit, verify_signatures, spec)
   321→            .map_err(|e| e.into_with_index(i))?;
   322→
   323→        initiate_validator_exit(state, exit.message.validator_index as usize, spec)?;
   324→    }
   325→    Ok(())
   326→}
   327→
   328→/// Validates each `bls_to_execution_change` and updates the state
   329→///
   330→/// Returns `Ok(())` if the validation and state updates completed successfully. Otherwise returns
   331→/// an `Err` describing the invalid object or cause of failure.
   332→pub fn process_bls_to_execution_changes<E: EthSpec>(
   333→    state: &mut BeaconState<E>,
   334→    bls_to_execution_changes: &[SignedBlsToExecutionChange],
   335→    verify_signatures: VerifySignatures,
   336→    spec: &ChainSpec,
   337→) -> Result<(), BlockProcessingError> {
   338→    for (i, signed_address_change) in bls_to_execution_changes.iter().enumerate() {
   339→        verify_bls_to_execution_change(state, signed_address_change, verify_signatures, spec)
   340→            .map_err(|e| e.into_with_index(i))?;
   341→
   342→        state
   343→            .get_validator_mut(signed_address_change.message.validator_index as usize)?
   344→            .change_withdrawal_credentials(
   345→                &signed_address_change.message.to_execution_address,
   346→                spec,
   347→            );
   348→    }
   349→
   350→    Ok(())
   351→}
   352→
   353→/// Validates each `Deposit` and updates the state, short-circuiting on an invalid object.
   354→///
   355→/// Returns `Ok(())` if the validation and state updates completed successfully, otherwise returns
   356→/// an `Err` describing the invalid object or cause of failure.
   357→pub fn process_deposits<E: EthSpec>(
   358→    state: &mut BeaconState<E>,
   359→    deposits: &[Deposit],
   360→    spec: &ChainSpec,
   361→) -> Result<(), BlockProcessingError> {
   362→    // [Modified in Electra:EIP6110]
   363→    // Disable former deposit mechanism once all prior deposits are processed
   364→    let deposit_requests_start_index = state.deposit_requests_start_index().unwrap_or(u64::MAX);
   365→    let eth1_deposit_index_limit = std::cmp::min(
   366→        deposit_requests_start_index,
   367→        state.eth1_data().deposit_count,
   368→    );
   369→
   370→    if state.eth1_deposit_index() < eth1_deposit_index_limit {
   371→        let expected_deposit_len = std::cmp::min(
   372→            E::MaxDeposits::to_u64(),
   373→            eth1_deposit_index_limit.safe_sub(state.eth1_deposit_index())?,
   374→        );
   375→        block_verify!(
   376→            deposits.len() as u64 == expected_deposit_len,
   377→            BlockProcessingError::DepositCountInvalid {
   378→                expected: expected_deposit_len as usize,
   379→                found: deposits.len(),
   380→            }
   381→        );
   382→    } else {
   383→        block_verify!(
   384→            deposits.len() as u64 == 0,
   385→            BlockProcessingError::DepositCountInvalid {
   386→                expected: 0,
   387→                found: deposits.len(),
   388→            }
   389→        );
   390→    }
   391→
   392→    // Verify merkle proofs in parallel.
   393→    deposits
   394→        .par_iter()
   395→        .enumerate()
   396→        .try_for_each(|(i, deposit)| {
   397→            verify_deposit_merkle_proof(
   398→                state,
   399→                deposit,
   400→                state.eth1_deposit_index().safe_add(i as u64)?,
   401→                spec,
   402→            )
   403→            .map_err(|e| e.into_with_index(i))
   404→        })?;
   405→
   406→    // Update the state in series.
   407→    for deposit in deposits {
   408→        apply_deposit(state, deposit.data.clone(), None, true, spec)?;
   409→    }
   410→
   411→    Ok(())
   412→}
   413→
   414→/// Process a single deposit, verifying its merkle proof if provided.
   415→pub fn apply_deposit<E: EthSpec>(
   416→    state: &mut BeaconState<E>,
   417→    deposit_data: DepositData,
   418→    proof: Option<FixedVector<Hash256, U33>>,
   419→    increment_eth1_deposit_index: bool,
   420→    spec: &ChainSpec,
   421→) -> Result<(), BlockProcessingError> {
   422→    let deposit_index = state.eth1_deposit_index() as usize;
   423→    if let Some(proof) = proof {
   424→        let deposit = Deposit {
   425→            proof,
   426→            data: deposit_data.clone(),
   427→        };
   428→        verify_deposit_merkle_proof(state, &deposit, state.eth1_deposit_index(), spec)
   429→            .map_err(|e| e.into_with_index(deposit_index))?;
   430→    }
   431→
   432→    if increment_eth1_deposit_index {
   433→        state.eth1_deposit_index_mut().safe_add_assign(1)?;
   434→    }
   435→
   436→    // Get an `Option<u64>` where `u64` is the validator index if this deposit public key
   437→    // already exists in the beacon_state.
   438→    let validator_index = get_existing_validator_index(state, &deposit_data.pubkey)
   439→        .map_err(|e| e.into_with_index(deposit_index))?;
   440→
   441→    let amount = deposit_data.amount;
   442→
   443→    if let Some(index) = validator_index {
   444→        // [Modified in Electra:EIP7251]
   445→        if let Ok(pending_deposits) = state.pending_deposits_mut() {
   446→            pending_deposits.push(PendingDeposit {
   447→                pubkey: deposit_data.pubkey,
   448→                withdrawal_credentials: deposit_data.withdrawal_credentials,
   449→                amount,
   450→                signature: deposit_data.signature,
   451→                slot: spec.genesis_slot, // Use `genesis_slot` to distinguish from a pending deposit request
   452→            })?;
   453→        } else {
   454→            // Update the existing validator balance.
   455→            increase_balance(state, index as usize, amount)?;
   456→        }
   457→    }
   458→    // New validator
   459→    else {
   460→        // The signature should be checked for new validators. Return early for a bad
   461→        // signature.
   462→        if is_valid_deposit_signature(&deposit_data, spec).is_err() {
   463→            return Ok(());
   464→        }
   465→
   466→        state.add_validator_to_registry(
   467→            deposit_data.pubkey,
   468→            deposit_data.withdrawal_credentials,
   469→            if state.fork_name_unchecked() >= ForkName::Electra {
   470→                0
   471→            } else {
   472→                amount
   473→            },
   474→            spec,
   475→        )?;
   476→
   477→        // [New in Electra:EIP7251]
   478→        if let Ok(pending_deposits) = state.pending_deposits_mut() {
   479→            pending_deposits.push(PendingDeposit {
   480→                pubkey: deposit_data.pubkey,
   481→                withdrawal_credentials: deposit_data.withdrawal_credentials,
   482→                amount,
   483→                signature: deposit_data.signature,
   484→                slot: spec.genesis_slot, // Use `genesis_slot` to distinguish from a pending deposit request
   485→            })?;
   486→        }
   487→    }
   488→
   489→    Ok(())
   490→}
   491→
   492→// Make sure to build the pubkey cache before calling this function
   493→pub fn process_withdrawal_requests<E: EthSpec>(
   494→    state: &mut BeaconState<E>,
   495→    requests: &[WithdrawalRequest],
   496→    spec: &ChainSpec,
   497→) -> Result<(), BlockProcessingError> {
   498→    for request in requests {
   499→        let amount = request.amount;
   500→        let is_full_exit_request = amount == spec.full_exit_request_amount;
   501→
   502→        // If partial withdrawal queue is full, only full exits are processed
   503→        if state.pending_partial_withdrawals()?.len() == E::pending_partial_withdrawals_limit()
   504→            && !is_full_exit_request
   505→        {
   506→            continue;
   507→        }
   508→
   509→        // Verify pubkey exists
   510→        let Some(validator_index) = state.pubkey_cache().get(&request.validator_pubkey) else {
   511→            continue;
   512→        };
   513→
   514→        let validator = state.get_validator(validator_index)?;
   515→        // Verify withdrawal credentials
   516→        let has_correct_credential = validator.has_execution_withdrawal_credential(spec);
   517→        let is_correct_source_address = validator
   518→            .get_execution_withdrawal_address(spec)
   519→            .map(|addr| addr == request.source_address)
   520→            .unwrap_or(false);
   521→
   522→        if !(has_correct_credential && is_correct_source_address) {
   523→            continue;
   524→        }
   525→
   526→        // Verify the validator is active
   527→        if !validator.is_active_at(state.current_epoch()) {
   528→            continue;
   529→        }
   530→
   531→        // Verify exit has not been initiated
   532→        if validator.exit_epoch != spec.far_future_epoch {
   533→            continue;
   534→        }
   535→
   536→        // Verify the validator has been active long enough
   537→        if state.current_epoch()
   538→            < validator
   539→                .activation_epoch
   540→                .safe_add(spec.shard_committee_period)?
   541→        {
   542→            continue;
   543→        }
   544→
   545→        let pending_balance_to_withdraw = state.get_pending_balance_to_withdraw(validator_index)?;
   546→        if is_full_exit_request {
   547→            // Only exit validator if it has no pending withdrawals in the queue
   548→            if pending_balance_to_withdraw == 0 {
   549→                initiate_validator_exit(state, validator_index, spec)?
   550→            }
   551→            continue;
   552→        }
   553→
   554→        let balance = state.get_balance(validator_index)?;
   555→        let has_sufficient_effective_balance =
   556→            validator.effective_balance >= spec.min_activation_balance;
   557→        let has_excess_balance = balance
   558→            > spec
   559→                .min_activation_balance
   560→                .safe_add(pending_balance_to_withdraw)?;
   561→
   562→        // Only allow partial withdrawals with compounding withdrawal credentials
   563→        if validator.has_compounding_withdrawal_credential(spec)
   564→            && has_sufficient_effective_balance
   565→            && has_excess_balance
   566→        {
   567→            let to_withdraw = std::cmp::min(
   568→                balance
   569→                    .safe_sub(spec.min_activation_balance)?
   570→                    .safe_sub(pending_balance_to_withdraw)?,
   571→                amount,
   572→            );
   573→            let exit_queue_epoch = state.compute_exit_epoch_and_update_churn(to_withdraw, spec)?;
   574→            let withdrawable_epoch =
   575→                exit_queue_epoch.safe_add(spec.min_validator_withdrawability_delay)?;
   576→            state
   577→                .pending_partial_withdrawals_mut()?
   578→                .push(PendingPartialWithdrawal {
   579→                    validator_index: validator_index as u64,
   580→                    amount: to_withdraw,
   581→                    withdrawable_epoch,
   582→                })?;
   583→        }
   584→    }
   585→    Ok(())
   586→}
   587→
   588→pub fn process_deposit_requests<E: EthSpec>(
   589→    state: &mut BeaconState<E>,
   590→    deposit_requests: &[DepositRequest],
   591→    spec: &ChainSpec,
   592→) -> Result<(), BlockProcessingError> {
   593→    for request in deposit_requests {
   594→        // Set deposit receipt start index
   595→        if state.deposit_requests_start_index()? == spec.unset_deposit_requests_start_index {
   596→            *state.deposit_requests_start_index_mut()? = request.index
   597→        }
   598→        let slot = state.slot();
   599→
   600→        // [New in Electra:EIP7251]
   601→        if let Ok(pending_deposits) = state.pending_deposits_mut() {
   602→            pending_deposits.push(PendingDeposit {
   603→                pubkey: request.pubkey,
   604→                withdrawal_credentials: request.withdrawal_credentials,
   605→                amount: request.amount,
   606→                signature: request.signature.clone(),
   607→                slot,
   608→            })?;
   609→        }
   610→    }
   611→
   612→    Ok(())
   613→}
   614→
   615→// Make sure to build the pubkey cache before calling this function
   616→pub fn process_consolidation_requests<E: EthSpec>(
   617→    state: &mut BeaconState<E>,
   618→    consolidation_requests: &[ConsolidationRequest],
   619→    spec: &ChainSpec,
   620→) -> Result<(), BlockProcessingError> {
   621→    for request in consolidation_requests {
   622→        process_consolidation_request(state, request, spec)?;
   623→    }
   624→
   625→    Ok(())
   626→}
   627→
   628→fn is_valid_switch_to_compounding_request<E: EthSpec>(
   629→    state: &BeaconState<E>,
   630→    consolidation_request: &ConsolidationRequest,
   631→    spec: &ChainSpec,
   632→) -> Result<bool, BlockProcessingError> {
   633→    // Switch to compounding requires source and target be equal
   634→    if consolidation_request.source_pubkey != consolidation_request.target_pubkey {
   635→        return Ok(false);
   636→    }
   637→
   638→    // Verify pubkey exists
   639→    let Some(source_index) = state
   640→        .pubkey_cache()
   641→        .get(&consolidation_request.source_pubkey)
   642→    else {
   643→        // source validator doesn't exist
   644→        return Ok(false);
   645→    };
   646→
   647→    let source_validator = state.get_validator(source_index)?;
   648→    // Verify the source withdrawal credentials
   649→    // Note: We need to specifically check for eth1 withdrawal credentials here
   650→    // If the validator is already compounding, the compounding request is not valid.
   651→    if let Some(withdrawal_address) = source_validator
   652→        .has_eth1_withdrawal_credential(spec)
   653→        .then(|| {
   654→            source_validator
   655→                .withdrawal_credentials
   656→                .as_slice()
   657→                .get(12..)
   658→                .map(Address::from_slice)
   659→        })
   660→        .flatten()
   661→    {
   662→        if withdrawal_address != consolidation_request.source_address {
   663→            return Ok(false);
   664→        }
   665→    } else {
   666→        // Source doesn't have eth1 withdrawal credentials
   667→        return Ok(false);
   668→    }
   669→
   670→    // Verify the source is active
   671→    let current_epoch = state.current_epoch();
   672→    if !source_validator.is_active_at(current_epoch) {
   673→        return Ok(false);
   674→    }
   675→    // Verify exits for source has not been initiated
   676→    if source_validator.exit_epoch != spec.far_future_epoch {
   677→        return Ok(false);
   678→    }
   679→
   680→    Ok(true)
   681→}
   682→
   683→pub fn process_consolidation_request<E: EthSpec>(
   684→    state: &mut BeaconState<E>,
   685→    consolidation_request: &ConsolidationRequest,
   686→    spec: &ChainSpec,
   687→) -> Result<(), BlockProcessingError> {
   688→    if is_valid_switch_to_compounding_request(state, consolidation_request, spec)? {
   689→        let Some(source_index) = state
   690→            .pubkey_cache()
   691→            .get(&consolidation_request.source_pubkey)
   692→        else {
   693→            // source validator doesn't exist. This is unreachable as `is_valid_switch_to_compounding_request`
   694→            // will return false in that case.
   695→            return Ok(());
   696→        };
   697→        state.switch_to_compounding_validator(source_index, spec)?;
   698→        return Ok(());
   699→    }
   700→
   701→    // Verify that source != target, so a consolidation cannot be used as an exit.
   702→    if consolidation_request.source_pubkey == consolidation_request.target_pubkey {
   703→        return Ok(());
   704→    }
   705→
   706→    // If the pending consolidations queue is full, consolidation requests are ignored
   707→    if state.pending_consolidations()?.len() == E::PendingConsolidationsLimit::to_usize() {
   708→        return Ok(());
   709→    }
   710→    // If there is too little available consolidation churn limit, consolidation requests are ignored
   711→    if state.get_consolidation_churn_limit(spec)? <= spec.min_activation_balance {
   712→        return Ok(());
   713→    }
   714→
   715→    let Some(source_index) = state
   716→        .pubkey_cache()
   717→        .get(&consolidation_request.source_pubkey)
   718→    else {
   719→        // source validator doesn't exist
   720→        return Ok(());
   721→    };
   722→    let Some(target_index) = state
   723→        .pubkey_cache()
   724→        .get(&consolidation_request.target_pubkey)
   725→    else {
   726→        // target validator doesn't exist
   727→        return Ok(());
   728→    };
   729→
   730→    let source_validator = state.get_validator(source_index)?;
   731→    // Verify the source withdrawal credentials
   732→    if let Some(withdrawal_address) = source_validator.get_execution_withdrawal_address(spec) {
   733→        if withdrawal_address != consolidation_request.source_address {
   734→            return Ok(());
   735→        }
   736→    } else {
   737→        // Source doen't have execution withdrawal credentials
   738→        return Ok(());
   739→    }
   740→
   741→    let target_validator = state.get_validator(target_index)?;
   742→    // Verify the target has compounding withdrawal credentials
   743→    if !target_validator.has_compounding_withdrawal_credential(spec) {
   744→        return Ok(());
   745→    }
   746→
   747→    // Verify the source and target are active
   748→    let current_epoch = state.current_epoch();
   749→    if !source_validator.is_active_at(current_epoch)
   750→        || !target_validator.is_active_at(current_epoch)
   751→    {
   752→        return Ok(());
   753→    }
   754→    // Verify exits for source and target have not been initiated
   755→    if source_validator.exit_epoch != spec.far_future_epoch
   756→        || target_validator.exit_epoch != spec.far_future_epoch
   757→    {
   758→        return Ok(());
   759→    }
   760→    // Verify the source has been active long enough
   761→    if current_epoch
   762→        < source_validator
   763→            .activation_epoch
   764→            .safe_add(spec.shard_committee_period)?
   765→    {
   766→        return Ok(());
   767→    }
   768→    // Verify the source has no pending withdrawals in the queue
   769→    if state.get_pending_balance_to_withdraw(source_index)? > 0 {
   770→        return Ok(());
   771→    }
   772→
   773→    // Initiate source validator exit and append pending consolidation
   774→    let source_exit_epoch = state
   775→        .compute_consolidation_epoch_and_update_churn(source_validator.effective_balance, spec)?;
   776→    let source_validator = state.get_validator_mut(source_index)?;
   777→    source_validator.exit_epoch = source_exit_epoch;
   778→    source_validator.withdrawable_epoch =
   779→        source_exit_epoch.safe_add(spec.min_validator_withdrawability_delay)?;
   780→    state
   781→        .pending_consolidations_mut()?
   782→        .push(PendingConsolidation {
   783→            source_index: source_index as u64,
   784→            target_index: target_index as u64,
   785→        })?;
   786→
   787→    Ok(())
   788→}
