     1→use super::errors::{BlockOperationError, IndexedAttestationInvalid as Invalid};
     2→use super::signature_sets::{get_pubkey_from_state, indexed_attestation_signature_set};
     3→use crate::VerifySignatures;
     4→use itertools::Itertools;
     5→use types::*;
     6→
     7→type Result<T> = std::result::Result<T, BlockOperationError<Invalid>>;
     8→
     9→fn error(reason: Invalid) -> BlockOperationError<Invalid> {
    10→    BlockOperationError::invalid(reason)
    11→}
    12→
    13→/// Verify an `IndexedAttestation`.
    14→pub fn is_valid_indexed_attestation<E: EthSpec>(
    15→    state: &BeaconState<E>,
    16→    indexed_attestation: IndexedAttestationRef<E>,
    17→    verify_signatures: VerifySignatures,
    18→    spec: &ChainSpec,
    19→) -> Result<()> {
    20→    let indices = indexed_attestation.attesting_indices_to_vec();
    21→
    22→    // Verify that indices aren't empty
    23→    verify!(!indices.is_empty(), Invalid::IndicesEmpty);
    24→
    25→    // Check that indices are sorted and unique
    26→    let check_sorted = |list: &[u64]| -> Result<()> {
    27→        list.iter()
    28→            .tuple_windows()
    29→            .enumerate()
    30→            .try_for_each(|(i, (x, y))| {
    31→                if x < y {
    32→                    Ok(())
    33→                } else {
    34→                    Err(error(Invalid::BadValidatorIndicesOrdering(i)))
    35→                }
    36→            })?;
    37→        Ok(())
    38→    };
    39→    check_sorted(&indices)?;
    40→
    41→    if verify_signatures.is_true() {
    42→        verify!(
    43→            indexed_attestation_signature_set(
    44→                state,
    45→                |i| get_pubkey_from_state(state, i),
